CUSTOM_PROVIDER_NAME = "Alfa on-premise"
_base_input_names = {field.name for field in LCModelComponent._base_inputs}
_custom_component_cls = OptionalStructuredOutputPatch
def _configure_custom_inputs(inputs, base_input_names):
    """Configure custom inputs from OptionalStructuredOutputPatch.

    NOTE: This MUST be a function (ast.FunctionDef + ast.Assign call), not a bare for-loop,
    because eval_custom_component_code / prepare_global_scope only executes
    ast.Import, ast.ImportFrom, ast.ClassDef, ast.FunctionDef, and ast.Assign nodes.
    A bare ast.For at module level is silently skipped, which causes input defaults
    (e.g. structured_output_strict) to never be applied when the component is loaded
    through the COMPONENT_REGISTRY path.
    """
    filtered = [
        inp for inp in inputs
        if getattr(inp, "name", None) not in base_input_names
    ]
    for inp in filtered:
        name = getattr(inp, "name", "")
        if name == "schema_json":
            inp.show = False
            inp.advanced = True
            inp.info = (
                "Поле заполняется автоматически на основе JSON Schema (text). "
                "Например, если передать JSON Schema как {\"answer\": {\"type\": \"boolean\"}}, "
                "то здесь будет сформирована структура вида {\"schema\": { ... }}."
            )
            inp.value = ""
        if name == "structured_output_strict":
            inp.display_name = "Строгая схема ответа"
            inp.show = False
            inp.advanced = False
            inp.info = (
                "Если включено — используем response_format=json_schema. "
                "Если выключено — используем response_format=json_object и просим модель следовать схеме через промпт."
            )
            inp.value = True
        if name == "temperature":
            inp.value = "0"
    return filtered

_custom_inputs = _configure_custom_inputs(_custom_component_cls.inputs, _base_input_names)
_custom_fields = {input_.name: input_.to_dict() for input_ in _custom_inputs}

MODEL_PROVIDERS_DICT = {
