    @classmethod
    def get_template_config(cls, component):
        template_config = Component.get_template_config(component)
        inputs = template_config.get("inputs") or []

        model_name_input = next((input_ for input_ in inputs if getattr(input_, "name", None) == "model_name"), None)
        system_id_input = next((input_ for input_ in inputs if getattr(input_, "name", None) == "system_id"), None)

        if model_name_input is not None and system_id_input is not None:
            build_config = {
                "model_name": model_name_input.to_dict(),
                "system_id": system_id_input.to_dict(),
            }
            run_until_complete(update_models(build_config, getattr(system_id_input, "value", None)))
            model_name_config = build_config.get("model_name") or {}
            model_name_input.options = model_name_config.get("options") or []
            model_name_input.value = model_name_config.get("value")
            model_name_input.refresh_button = model_name_config.get("refresh_button", getattr(model_name_input, "refresh_button", None))

        return template_config

    def _get_provider_info(self):
        if not isinstance(self.model_provider, str):
            msg = "Неизвестный провайдер модели."
            raise ValueError(msg)
        provider_info = MODEL_PROVIDERS_DICT.get(self.model_provider)
        if not provider_info:
            logger.warning(
                f"Неизвестный провайдер {self.model_provider}. Использую провайдер по умолчанию {CUSTOM_PROVIDER_NAME}.",
            )
            self.model_provider = CUSTOM_PROVIDER_NAME
            provider_info = MODEL_PROVIDERS_DICT[self.model_provider]
        return provider_info

    def _collect_provider_kwargs(self, provider_info: dict[str, Any]) -> dict[str, Any]:
        inputs = provider_info.get("inputs") or []
        return {
            input_.name: getattr(self, input_.name)
            for input_ in inputs
        }

    def _build_llm(self, tool_choice: str = "none"):
        provider_info = self._get_provider_info()
        component_class = provider_info.get("component_class")
        model_kwargs = self._collect_provider_kwargs(provider_info)
        model_kwargs["tool_choice"] = tool_choice
        language_model = component_class().set(**model_kwargs).build_model()
        display_name = get_model_name(language_model, display_name=component_class.display_name)
        return language_model, display_name

    def _get_llm(self):
        # В этом компоненте инструменты не используются, поэтому явно отключаем tool_choice
        return self._build_llm(tool_choice="none")

    def _message_to_text(self, value) -> str:
        if isinstance(value, dict):
            return json.dumps(value, ensure_ascii=False)
        return normalize_message_like_text(value)

    def _prepare_schema_json(self) -> dict[str, Any]:
        schema_source_text = getattr(self, "schema_text_input", None)
        raw_schema = self._message_to_text(schema_source_text).strip() if schema_source_text is not None else ""
        if not raw_schema:
            msg = "Поле JSON Schema не должно быть пустым."
            raise ValueError(msg)

        try:
            schema_obj = json.loads(raw_schema)
        except json.JSONDecodeError:
            try:
                schema_obj = ast.literal_eval(raw_schema)
            except (ValueError, SyntaxError) as exc:
                msg = "Не удалось распарсить JSON Schema. Убедитесь, что передан корректный JSON или Python-словарь."
                raise ValueError(msg) from exc
        if not isinstance(schema_obj, dict):
            msg = "JSON Schema должна быть словарём."
            raise ValueError(msg)

        schema_payload = self._normalize_schema_payload(schema_obj)
        schema_body = schema_payload["schema"]
        if self._is_structured_output_strict():
            self._validate_openai_structured_schema(schema_body)
        else:
            try:
                Draft202012Validator.check_schema(schema_body)
            except SchemaError as exc:
                path = self._format_path(exc.absolute_path)
                raise ValueError(f"Переданная JSON Schema некорректна в {path}: {exc.message}") from exc
        self.schema_json = json.dumps(schema_payload, ensure_ascii=False)
        return schema_body

    def _normalize_json_schema_node(self, schema_node: Any) -> Any:
        if isinstance(schema_node, list):
            return [self._normalize_json_schema_node(item) for item in schema_node]
        if not isinstance(schema_node, dict):
            return schema_node

        normalized = dict(schema_node)

        if "$ref" in normalized:
            return normalized

        if "properties" in normalized:
            properties = normalized["properties"]
            if not isinstance(properties, dict):
                msg = "Поле properties должно содержать словарь с описанием атрибутов."
                raise ValueError(msg)
            normalized["properties"] = {
                key: self._normalize_json_schema_node(value)
                for key, value in properties.items()
            }

        items = normalized.get("items")
        if items is not None:
            normalized["items"] = self._normalize_json_schema_node(items)

        if "anyOf" in normalized:
            any_of = normalized["anyOf"]
            if not isinstance(any_of, list) or not any_of:
                msg = "Поле anyOf должно быть непустым списком."
                raise ValueError(msg)
            normalized["anyOf"] = [self._normalize_json_schema_node(item) for item in any_of]

        for defs_key in ("$defs", "definitions"):
            if defs_key in normalized:
                defs = normalized[defs_key]
                if not isinstance(defs, dict):
                    msg = f"Поле {defs_key} должно быть словарём."
                    raise ValueError(msg)
                normalized[defs_key] = {
                    key: self._normalize_json_schema_node(value)
                    for key, value in defs.items()
                }

        if normalized.get("type") == "object" or "properties" in normalized:
            properties = normalized.get("properties") or {}
            if not isinstance(properties, dict):
                msg = "Поле properties должно содержать словарь с описанием атрибутов."
                raise ValueError(msg)
            normalized["type"] = "object"
            normalized["properties"] = properties
            normalized["required"] = list(properties.keys())
            normalized["additionalProperties"] = False

        return normalized

    def _normalize_schema_payload(self, schema_obj: dict[str, Any]) -> dict[str, Any]:
        if "json_schema" in schema_obj and isinstance(schema_obj["json_schema"], dict):
            schema_obj = schema_obj["json_schema"]

        if "schema" in schema_obj and isinstance(schema_obj["schema"], dict):
            schema_payload = dict(schema_obj)
        else:
            schema_payload = {"schema": schema_obj}

        if not isinstance(schema_payload.get("schema"), dict):
            msg = "Поле schema должно содержать словарь с описанием JSON Schema."
            raise ValueError(msg)

        schema_body = schema_payload["schema"]

        if "type" not in schema_body and "properties" not in schema_body and "anyOf" not in schema_body:
            if all(isinstance(value, dict) for value in schema_body.values()) and schema_body:
                schema_body = {
                    "type": "object",
                    "properties": schema_body,
                    "required": sorted(schema_body.keys()),
                }
            else:
                msg = "Невозможно вывести JSON Schema из переданного значения. Добавьте ключи type/properties."
                raise ValueError(msg)

        schema_body = self._normalize_json_schema_node(schema_body)
        if "anyOf" in schema_body:
            msg = "Корневая JSON Schema должна описывать объект и не может использовать anyOf."
            raise ValueError(msg)
        if schema_body.get("type") != "object":
            msg = "Корневая JSON Schema должна описывать объект."
            raise ValueError(msg)
        if "properties" not in schema_body or not isinstance(schema_body["properties"], dict):
            msg = "Поле properties должно содержать словарь с описанием атрибутов."
            raise ValueError(msg)

        schema_payload["schema"] = schema_body

        if not schema_payload.get("name"):
            schema_payload["name"] = "StructuredResponse"

        return schema_payload

    def _is_structured_output_strict(self) -> bool:
        return bool(getattr(self, "structured_output_strict", True))

    def _format_path(self, parts: Any) -> str:
        path = "$"
        for part in parts:
            if isinstance(part, int):
                path += f"[{part}]"
            else:
                path += f".{part}"
        return path

    def _validate_openai_structured_schema(self, schema_body: dict[str, Any]) -> None:
        try:
            Draft202012Validator.check_schema(schema_body)
        except SchemaError as exc:
            path = self._format_path(exc.absolute_path)
            msg = f"Переданная JSON Schema некорректна в {path}: {exc.message}"
            raise ValueError(msg) from exc

        stats = {
            "total_properties": 0,
            "total_enum_values": 0,
            "total_string_budget": 0,
        }

        def scan(schema_node: Any, path: list[Any], depth: int) -> None:
            if isinstance(schema_node, list):
                for index, item in enumerate(schema_node):
                    scan(item, [*path, index], depth)
                return
            if not isinstance(schema_node, dict):
                return

            formatted_path = self._format_path(path)

            unsupported_keywords = sorted(OPENAI_STRUCTURED_OUTPUT_UNSUPPORTED_KEYWORDS.intersection(schema_node))
            if unsupported_keywords:
                unsupported_list = ", ".join(unsupported_keywords)
                msg = (
                    "JSON Schema содержит ключевые слова, не поддерживаемые Structured Outputs: "
                    f"{unsupported_list} в {formatted_path}."
                )
                raise ValueError(msg)

            const_value = schema_node.get("const")
            if isinstance(const_value, str):
                stats["total_string_budget"] += len(const_value)

            enum_values = schema_node.get("enum")
            if isinstance(enum_values, list):
                stats["total_enum_values"] += len(enum_values)
                string_enum_budget = 0
                for enum_value in enum_values:
                    if isinstance(enum_value, str):
                        value_length = len(enum_value)
                        stats["total_string_budget"] += value_length
                        string_enum_budget += value_length

            properties = schema_node.get("properties")
            if isinstance(properties, dict):
                stats["total_properties"] += len(properties)
                for property_name, property_schema in properties.items():
                    stats["total_string_budget"] += len(property_name)
                    scan(property_schema, [*path, property_name], depth + 1)

            for defs_key in ("$defs", "definitions"):
                defs = schema_node.get(defs_key)
                if isinstance(defs, dict):
                    for def_name, def_schema in defs.items():
                        stats["total_string_budget"] += len(def_name)
                        scan(def_schema, [*path, defs_key, def_name], depth + 1)

            items = schema_node.get("items")
            if items is not None:
                scan(items, [*path, "items"], depth + 1)

            any_of = schema_node.get("anyOf")
            if isinstance(any_of, list):
                for index, option in enumerate(any_of):
                    scan(option, [*path, "anyOf", index], depth + 1)

        scan(schema_body, [], 1)

    def _set_structured_output_field_visibility(self, build_config: dotdict, enabled: bool) -> None:
        for field_name in ("schema_text_input", "structured_output_strict"):
            field = build_config.get(field_name)
            if isinstance(field, dict):
                field["show"] = bool(enabled)

    def _update_input_types(self, build_config: dotdict) -> dotdict:
        for key, value in build_config.items():
            if isinstance(value, dict):
                if value.get("input_types") is None:
                    build_config[key]["input_types"] = []
            elif hasattr(value, "input_types") and value.input_types is None:
                value.input_types = []
        return build_config

    def _normalize_structured_output(self, parsed_json: Any) -> list[Any]:
        if isinstance(parsed_json, dict):
            objects = parsed_json.get("objects", parsed_json)
        else:
            objects = parsed_json

        if isinstance(objects, dict):
            objects = [objects]

        if not isinstance(objects, list):
            msg = "Структурированный ответ должен быть словарем или списком."
            raise ValueError(msg)

        return objects

    def _validate_structured_output(self, output: list[Any] | None) -> list[Any]:
        if not isinstance(output, list) or not output:
            msg = "No structured output returned"
            raise ValueError(msg)
        return output

    def _get_repair_llm(self):
        """Создать LLM для перевода (без tool_choice)."""
        def _build():
            model, _ = self._build_llm(tool_choice="none")
            return model

        return lang.get_cached_llm(self, "_repair_llm", _build)

    def _start_component_trace_span(self, *, need_structured_output: bool):
        graph = getattr(self, "graph", None)
        context = getattr(graph, "context", {}) if graph else {}
        if not isinstance(context, dict):
            return None
        flow_trace = context.get("langfuse_flow_trace") or context.get("langfuse_trace")
        if flow_trace is None:
            return None
        try:
            return flow_trace.span(
                name=self.display_name,
                input={
                    "user_prompt": self._message_to_text(getattr(self, "user_prompt", "")),
                    "structured_output": bool(getattr(self, "enable_structured_output", False)),
                    "need_structured_output": need_structured_output,
                    "model_provider": getattr(self, "model_provider", None),
                },
                metadata={
                    "trace_kind": "node_execution",
                    "component_name": self.display_name,
                    "component_type": self.__class__.__name__,
                },
            )
        except Exception:
            return None

    async def _invoke_llm_with_language_check(
        self,
        *,
        language_model,
        messages: list[BaseMessage],
        structured_output_enabled: bool
    ) -> tuple[Any, str]:
        response_message = await language_model.ainvoke(messages)
        raw_text = lang.extract_text_from_llm_response(response_message)

        # Для структурированного вывода или если проверка отключена — возвращаем как есть
        if structured_output_enabled or not bool(getattr(self, "check_language_output", False)):
            return response_message, raw_text

        # Проверяем язык с ретраями и переводом
        async def on_retry():
            retry_response = await language_model.ainvoke(messages)
            return lang.extract_text_from_llm_response(retry_response)

        max_retries = lang.get_language_check_retries(self)
        final_text, _ = await lang.ensure_russian_response(
            text=raw_text,
            llm_for_translation=self._get_repair_llm,
            extract_text_fn=lang.extract_text_from_llm_response,
            max_retries=max_retries,
            on_retry=on_retry,
        )

        return response_message, final_text

    def _extract_structured_json(self, response_message: Any, raw_text: str) -> Any:
        additional_kwargs = getattr(response_message, "additional_kwargs", None) or {}
        response_metadata = getattr(response_message, "response_metadata", None) or {}
        content = getattr(response_message, "content", None)

        refusal = additional_kwargs.get("refusal")
        if refusal:
            msg = f"Модель отказалась вернуть structured output: {refusal}"
            raise ValueError(msg)

        finish_reason = response_metadata.get("finish_reason")
        if finish_reason in {"length", "content_filter"}:
            msg = (
                "Structured output не был завершен корректно: "
                f"finish_reason={finish_reason}. Сырой ответ: {raw_text}"
            )
            raise ValueError(msg)

        if finish_reason not in (None, "stop"):
            msg = f"Неожиданный finish_reason для structured output: {finish_reason}"
            raise ValueError(msg)

        parsed = additional_kwargs.get("parsed")
        if parsed is not None:
            if hasattr(parsed, "model_dump"):
                return parsed.model_dump()
            if hasattr(parsed, "dict"):
                return parsed.dict()
            return parsed
        if isinstance(content, dict):
            return content

        try:
            return json.loads(raw_text)
        except json.JSONDecodeError as exc:
            msg = f"Ответ модели не является корректным JSON: {raw_text}"
            logger.error(msg)
            raise ValueError(msg) from exc

    async def _generate_response_payload(
        self,
        *,
        need_structured_output: bool = False,
        set_status: bool = False,
    ) -> tuple[Message, list[Any] | None]:
        component_span = self._start_component_trace_span(
            need_structured_output=need_structured_output
        )
        try:
            structured_output_enabled = bool(getattr(self, "enable_structured_output", False))

            if need_structured_output and not structured_output_enabled:
                raise ValueError("Необходимо включить структурированный ответ JSON для получения структурированных данных.")

            self.schema_json = ""

            if structured_output_enabled:
                self._prepare_schema_json()

            language_model, display_name = self._get_llm()

            system_prompt = self._message_to_text(getattr(self, "system_prompt", ""))
            raw_user_prompt = getattr(self, "user_prompt", None)
            user_prompt = self._message_to_text(self.user_prompt)
            if not user_prompt:
                raise ValueError("Пользовательский запрос не должен быть пустым.")

            history_messages: list[BaseMessage] = []
            if getattr(self, "enable_memory", False):
                history_messages = await get_langchain_history(
                    self,
                    dedupe_text=user_prompt,
                    current_input=raw_user_prompt,
                )

            messages: list[BaseMessage] = []
            if system_prompt:
                messages.append(SystemMessage(content=system_prompt))
            messages.extend(history_messages)
            messages.append(HumanMessage(content=user_prompt))

            response_message, raw_text = await self._invoke_llm_with_language_check(
                language_model=language_model,
                messages=messages,
                structured_output_enabled=structured_output_enabled,
            )

            structured_output: list[Any] | None = None
            result_text = raw_text

            if structured_output_enabled:
                parsed_json = self._extract_structured_json(response_message, raw_text)
                if need_structured_output:
                    structured_output = self._normalize_structured_output(parsed_json)
                result_text = json.dumps(parsed_json, ensure_ascii=False, indent=2)
                logger.debug(f"Получен структурированный ответ от {display_name}")
            else:
                logger.debug(f"Получен ответ от {display_name} без структурированного ответа")

            result_message = Message(text=result_text)
            if set_status:
                self.status = result_message
            if component_span is not None:
                try:
                    component_span.end(
                        output=result_text,
                        metadata={
                            "status": "success",
                            "trace_kind": "node_execution",
                            "model": display_name,
                        },
                    )
                except Exception:
                    pass

            return result_message, structured_output
        except Exception as exc:
            error_meta = normalize_exception(exc, stage=ERROR_STAGE_LLM)
            if component_span is not None:
                try:
                    component_span.end(
                        output={"error": error_meta.get("error_summary") or str(exc)},
                        level="ERROR",
                        status_message=error_meta.get("error_summary") or str(exc),
                        metadata={
                            "status": "error",
                            "trace_kind": "node_execution",
                            **error_meta,
                        },
                    )
                except Exception:
                    pass
            propagate_error_to_flow_trace(exc, stage=ERROR_STAGE_LLM, graph=self.graph)
            raise

    async def generate_llm_response(self) -> Message:
        result_message, _ = await self._generate_response_payload(set_status=True)
        return result_message

    async def generate_structured_data(self) -> Data:
        _, structured_output = await self._generate_response_payload(
            need_structured_output=True,
            set_status=True,
        )
        output = self._validate_structured_output(structured_output)
        if len(output) == 1:
            return Data(data=output[0])
        return Data(data={"results": output})

    async def generate_structured_dataframe(self) -> DataFrame:
        _, structured_output = await self._generate_response_payload(
            need_structured_output=True,
            set_status=True,
        )
        output = self._validate_structured_output(structured_output)
        if len(output) == 1:
            return DataFrame([output[0]])
        return DataFrame(output)

    def set_component_params(self, component_class):
        provider_info = MODEL_PROVIDERS_DICT.get(self.model_provider)
        if not provider_info:
            return component_class()

        model_kwargs = self._collect_provider_kwargs(provider_info)
        return component_class().set(**model_kwargs)

    async def update_build_config(self, build_config: dotdict, field_value: str, field_name: str | None = None) -> dotdict:
        if field_name in (None, "model_provider", "model_name", "system_id"):
            await update_models(build_config, field_value if field_name == "system_id" else self.system_id)
        if field_name in ("model_provider",):
            build_config["model_provider"]["value"] = field_value
            self.model_provider = field_value
            lang.invalidate_cached_llm(self, "_repair_llm")

            provider_info = MODEL_PROVIDERS_DICT.get(field_value, {})
            provider_fields = provider_info.get("fields", {})
            build_config.update(provider_fields)
            build_config["model_provider"]["input_types"] = []

            component_class = provider_info.get("component_class") if provider_info else None
            if component_class and hasattr(component_class, "update_build_config"):
                component_instance = self.set_component_params(component_class)
                model_config = build_config.get("model_name")
                model_value = model_config.get("value") if isinstance(model_config, dict) else None
                build_config = await update_component_build_config(
                    component_instance,
                    build_config,
                    model_value,
                    "model_name",
                )

            expected_keys = {
                getattr(component_input, "name")
                for component_input in self.inputs
                if getattr(component_input, "name", None)
            }
            missing_keys = sorted(expected_keys - set(build_config))
            if missing_keys:
                logger.warning(f"В build_config отсутствуют ожидаемые поля компонента: {missing_keys}")

        if (
            isinstance(self.model_provider, str)
            and self.model_provider in MODEL_PROVIDERS_DICT
            and field_name in MODEL_DYNAMIC_UPDATE_FIELDS
        ):
            provider_info = MODEL_PROVIDERS_DICT.get(self.model_provider)
            if provider_info:
                lang.invalidate_cached_llm(self, "_repair_llm")
                component_class = provider_info.get("component_class")
                component_instance = self.set_component_params(component_class) if component_class else None
                if component_instance and hasattr(component_instance, "update_build_config"):
                    build_config = await update_component_build_config(
                        component_instance,
                        build_config,
                        field_value,
                        field_name,
                    )

        if field_name == "enable_memory":
            self.enable_memory = build_config["enable_memory"]["value"] = bool(field_value)
        elif field_name == "enable_structured_output":
            self.enable_structured_output = build_config["enable_structured_output"]["value"] = bool(field_value)
        elif field_name == "structured_output_strict":
            self.structured_output_strict = build_config["structured_output_strict"]["value"] = bool(field_value)
        elif field_name == "system_id":
            self.system_id = build_config["system_id"]["value"] = field_value

        memory_field_names = {input_.name for input_ in self.memory_inputs}
        if field_name in memory_field_names:
            try:
                memory_component = MemoryComponent(**self.get_base_args())
                memory_kwargs = {
                    input_.name: getattr(self, input_.name, None) for input_ in self.memory_inputs
                }
                memory_kwargs.setdefault("mode", "Retrieve")
                memory_component = memory_component.set(**memory_kwargs)
                updated_config = memory_component.update_build_config(build_config, field_value, field_name)
                if isinstance(updated_config, dotdict):
                    build_config = updated_config
            except Exception as exc:
                logger.debug(f"Не удалось делегировать обновление памяти: {exc}")

        structured_output_config = build_config.get("enable_structured_output")
        structured_output_enabled = bool(
            structured_output_config.get("value") if isinstance(structured_output_config, dict) else False
        )
        self._set_structured_output_field_visibility(build_config, structured_output_enabled)
        build_config = self._update_input_types(build_config)

        return dotdict({k: v.to_dict() if hasattr(v, "to_dict") else v for k, v in build_config.items()})

